        language: 'python',
        content: `"""\nСервис определения языка контента\n"""\nfrom typing import Optional, Dict\nfrom bs4 import BeautifulSoup\n\nfrom infrastructure import LANG_RANGES, LANGUAGE_THRESHOLDS\n\n\nclass LanguageDetector:\n    """\n    Детектор языка на основе анализа символов\n    """\n\n    @classmethod\n    def count_chars_in_ranges(cls, text: str, ranges: list) -> int:\n        """Подсчитать количество символов в указанных Unicode диапазонах"""\n        count = 0\n        for char in text:\n            code = ord(char)\n            for start, end in ranges:\n                if start <= code <= end:\n                    count += 1\n                    break\n        return count\n\n    @classmethod\n    def detect_language(cls, text: str) -> Optional[str]:\n        """\n        Определить язык по характерным символам\n        Возвращает: 'zh', 'ja', 'ko', 'ru', 'en' или None\n        """\n        if not text or len(text.strip()) == 0:\n            return None\n\n        # Берём первые 5000 символов для скорости\n        sample = text[:5000]\n\n        results: Dict[str, int] = {}\n\n        # Считаем символы для каждого языка\n        for lang, ranges in LANG_RANGES.items():\n            count = cls.count_chars_in_ranges(sample, ranges)\n            if count >= LANGUAGE_THRESHOLDS.get(lang, 0):\n                results[lang] = count\n\n        # Для китайского/японского нужна дополнительная проверка\n        # потому что они используют общие иероглифы\n        if 'zh' in results and 'ja' in results:\n            # Если есть хирагана/катакана - это японский\n            ja_hiragana = cls.count_chars_in_ranges(sample, LANG_RANGES['ja'][0:2])\n            if ja_hiragana >= 3:\n                return 'ja'\n            else:\n                return 'zh'\n\n        # Возвращаем язык с наибольшим количеством символов\n        if results:\n            return max(results, key=results.get)\n\n        # Если ничего не найдено, проверяем на латиницу\n        latin_count = sum(1 for c in sample if c.isascii() and c.isalpha())\n        if latin_count >= 10:\n            return 'en'\n\n        return None\n\n\ndef detect_language_from_html(html_content: str) -> Optional[str]:\n    """\n    Определить язык из HTML-контента\n    """\n    soup = BeautifulSoup(html_content, 'html.parser')\n\n    # Удаляем скрипты и стили\n    for script in soup(["script", "style"]):\n        script.decompose()\n\n    # Получаем текст из основных контентных элементов\n    # Это важно - берём текст только из потенциального контента\n    content_tags = ['article', 'main', 'section', 'div', 'p']\n    text_parts = []\n\n    for tag in content_tags:\n        elements = soup.find_all(tag)\n        for elem in elements:\n            text = elem.get_text(strip=True)\n            # Берём только элементы с достаточным количеством текста\n            if len(text) > 50:\n                text_parts.append(text)\n\n    # Объединяем текст\n    text = ' '.join(text_parts)\n\n    if not text:\n        # Фоллбэк - берём весь текст\n        text = soup.get_text()\n\n    return LanguageDetector.detect_language(text)\n`,
        size: 3002
