        language: 'python',
        content: `"""\nМенеджер справочных данных\nПредоставляет доступ к справочным таблицам из БД\n"""\nfrom typing import List, Dict, Optional\nfrom infrastructure.database import DatabaseManager\n\n\nclass ReferenceManager:\n    """Менеджер для доступа к справочным данным из БД"""\n\n    _instance: Optional['ReferenceManager'] = None\n    _initialized: bool = False\n\n    def __new__(cls):\n        if cls._instance is None:\n            cls._instance = super().__new__(cls)\n        return cls._instance\n\n    def __init__(self):\n        if not self._initialized:\n            self.db_manager = DatabaseManager()\n            self._load_references()\n            ReferenceManager._initialized = True\n\n    def _load_references(self):\n        """Загрузить все справочные данные из БД"""\n        self.chapter_indicators = self.db_manager.get_chapter_indicators()\n        self.nav_indicators = self.db_manager.get_nav_indicators()\n        self.next_indicators = self.db_manager.get_next_indicators()\n        self.content_selectors = self.db_manager.get_content_selectors()\n        self.chinese_variations = self.db_manager.get_chinese_variations()\n\n    def get_chapter_indicators(self) -> List[str]:\n        """Получить индикаторы глав"""\n        return self.chapter_indicators\n\n    def get_nav_indicators(self) -> List[str]:\n        """Получить навигационные индикаторы"""\n        return self.nav_indicators\n\n    def get_next_indicators(self) -> List[str]:\n        """Получить индикаторы следующей главы"""\n        return self.next_indicators\n\n    def get_content_selectors(self) -> List[dict]:\n        """Получить селекторы контента"""\n        return self.content_selectors\n\n    def get_chinese_variations(self, base_keyword: str = None) -> Dict[str, List[str]]:\n        """Получить вариации китайских ключевых слов"""\n        if base_keyword:\n            return {base_keyword: self.chinese_variations.get(base_keyword, [])}\n        return self.chinese_variations\n\n    def get_chinese_variation_list(self, base_keyword: str) -> List[str]:\n        """Получить список вариаций для конкретного ключевого слова"""\n        return self.chinese_variations.get(base_keyword, [])\n\n    def refresh(self):\n        """Обновить справочные данные из БД"""\n        self._load_references()\n\n\n# Глобальный экземпляр для использования в сервисах\n_ref_manager: Optional[ReferenceManager] = None\n\n\ndef get_reference_manager() -> ReferenceManager:\n    """Получить глобальный экземпляр ReferenceManager"""\n    global _ref_manager\n    if _ref_manager is None:\n        _ref_manager = ReferenceManager()\n    return _ref_manager\n`,
