        path: `yin-yang_parser\\services\\cloudflare_detector.py`,
        language: 'python',
        content: `"""\nProtection Detector - обнаружение защит и ограничений\nОтветственность: Обнаружение Cloudflare, cookie баннеров, SPA и предупреждение о задержках\n"""\nimport re\nfrom typing import Optional, Tuple\n\n\nclass ProtectionDetector:\n    """Детектор защит и ограничений"""\n\n    # Паттерны для обнаружения Cloudflare\n    CLOUDFLARE_PATTERNS = [\n        r'Error\\s*1016',\n        r'Error\\s*1020',\n        r'Checking\\s*your\\s*browser',\n        r'cf-browser-verification',\n        r'Just\\s*a\\s*moment',\n        r'Cloudflare\\s*Ray\\s*ID',\n        r'Origin\\s*DNS\\s*error',\n        r'Access\\s*denied',\n        r'429',\n        r'Too\\s*Many\\s*Requests',\n    ]\n\n    # Статус-коды Cloudflare\n    CLOUDFLARE_STATUS_CODES = [403, 429, 503, 520, 521, 522, 523, 524, 525, 526, 527, 530]\n\n    # Паттерны cookie баннеров (GDPR, CCPA)\n    COOKIE_BANNER_PATTERNS = [\n        r'cookie\\s*consent',\n        r'accept\\s*cookies',\n        r'decline\\s*cookies',\n        r'manage\\s*cookies',\n        r'cookie\\s*settings',\n        r'we\\s*use\\s*cookies',\n        r'privacy\\s*settings',\n        r'uniconsent',\n        r'OneTrust',\n        r'Cookiebot',\n        r'Osano',\n        r'GDPR',\n        r'CCPA',\n    ]\n\n    # Паттерны SPA (React, Vue, Angular)\n    SPA_PATTERNS = [\n        r'<div\\s+id=["\\']root["\\']',\n        r'<div\\s+id=["\\']app["\\']',\n        r'<script[^>]+src=["\\'][^"\\']*main\\.[^"\\']*\\.js["\\']',\n        r'<noscript[^>]*>.*enable\\s*JavaScript',\n        r'You need to enable JavaScript',\n    ]\n\n    def is_cloudflare_page(self, html_content: str, status_code: int = None) -> bool:\n        """\n        Проверить, является ли страница страницей Cloudflare\n\n        Args:\n            html_content: HTML строка\n            status_code: HTTP статус-код (опционально)\n\n        Returns:\n            True если это Cloudflare\n        """\n        # Проверяем статус-код первым делом\n        if status_code and status_code in self.CLOUDFLARE_STATUS_CODES:\n            return True\n\n        # Проверяем контент страницы\n        for pattern in self.CLOUDFLARE_PATTERNS:\n            if re.search(pattern, html_content, re.IGNORECASE):\n                return True\n        return False\n\n    def has_cookie_banner(self, html_content: str) -> bool:\n        """\n        Проверить наличие cookie баннера\n\n        Args:\n            html_content: HTML строка\n\n        Returns:\n            True если есть cookie баннер\n        """\n        for pattern in self.COOKIE_BANNER_PATTERNS:\n            if re.search(pattern, html_content, re.IGNORECASE):\n                return True\n        return False\n\n    def is_spa_page(self, html_content: str) -> bool:\n        """\n        Проверить, является ли страница SPA (React/Vue/Angular)\n\n        Args:\n            html_content: HTML строка\n\n        Returns:\n            True если это SPA\n        """\n        for pattern in self.SPA_PATTERNS:\n            if re.search(pattern, html_content, re.IGNORECASE):\n                return True\n        return False\n\n    def detect_protection_type(self, html_content: str, status_code: int = None) -> Tuple[bool, bool, bool]:\n        """\n        Определить тип защиты/ограничений\n\n        Args:\n            html_content: HTML строка\n            status_code: HTTP статус-код (опционально)\n\n        Returns:\n            Кортеж (is_cloudflare, has_cookie_banner, is_spa)\n        """\n        is_cf = self.is_cloudflare_page(html_content, status_code)\n        has_cookie = self.has_cookie_banner(html_content)\n        is_spa = self.is_spa_page(html_content)\n        return is_cf, has_cookie, is_spa\n`,
