        content: `<!DOCTYPE html>\n<html lang="ru">\n<head>\n  <meta charset="UTF-8" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0"/>\n  <title>AICE Assistant</title>\n  <style>\n    html, body {\n      margin: 0;\n      padding: 0;\n      height: 100%;\n      overflow: hidden;\n      font-family: Arial, sans-serif;\n    }\n    iframe {\n      width: 100%;\n      height: 100%;\n      border: none;\n    }\n    #loading {\n      position: absolute;\n      top: 50%;\n      left: 50%;\n      transform: translate(-50%, -50%);\n      text-align: center;\n      color: #666;\n    }\n    #error {\n      position: absolute;\n      top: 50%;\n      left: 50%;\n      transform: translate(-50%, -50%);\n      text-align: center;\n      color: #d32f2f;\n      max-width: 80%;\n      display: none;\n    }\n  </style>\n</head>\n<body>\n  <div id="loading">Загрузка...</div>\n  <div id="error"></div>\n  <iframe id="ui-frame" src=""></iframe>\n  <script>\n    const BACKEND_URL = "https://ru-dtc-taice01.intercomp.ru/";\n    const iframe = document.getElementById("ui-frame");\n    const loadingEl = document.getElementById("loading");\n    const errorEl = document.getElementById("error");\n\n    function showError(msg) {\n      errorEl.textContent = msg;\n      errorEl.style.display = "block";\n      loadingEl.style.display = "none";\n    }\n\n    // Пробуем получить JWT через background.js\n    console.log("[Sidebar] Запрос JWT...");\n    \n    chrome.runtime.sendMessage({ type: "AUTH_REQUEST" }, (response) => {\n      console.log("[Sidebar] Ответ от SW:", response);\n      \n      if (chrome.runtime.lastError) {\n        console.error("[Sidebar] Ошибка runtime:", chrome.runtime.lastError);\n        showError("Ошибка Service Worker: " + chrome.runtime.lastError.message);\n        // Всё равно загружаем iframe\n        loadIframe(null);\n        return;\n      }\n      \n      if (response && response.success && response.token) {\n        localStorage.setItem("jwt_token", response.token);\n        console.log("[Sidebar] JWT получен");\n        loadIframe(response.token);\n      } else {\n        console.warn("[Sidebar] JWT не получен, загружаем без токена");\n        loadIframe(null);\n      }\n    });\n\n    function loadIframe(token) {\n      console.log("[Sidebar] Загрузка iframe:", BACKEND_URL + "/ui/");\n      iframe.src = BACKEND_URL + "/ui/";\n      \n      iframe.onload = () => {\n        console.log("[Sidebar] iframe загружен");\n        loadingEl.style.display = "none";\n        if (token) {\n          iframe.contentWindow.postMessage({\n            type: "JWT_TOKEN",\n            token: token\n          }, BACKEND_URL);\n          console.log("[Sidebar] Токен отправлен в iframe");\n        }\n      };\n      \n      iframe.onerror = () => {\n        console.error("[Sidebar] Ошибка загрузки iframe");\n        showError("Не удалось загрузить UI");\n      };\n    }\n\n    // Слушаем запросы на обновление токена от iframe\n    window.addEventListener("message", (event) => {\n      console.log("[Sidebar] Сообщение:", event);\n      if (event.origin !== BACKEND_URL) return;\n\n      if (event.data && event.data.type === "REFRESH_TOKEN_REQUEST") {\n        chrome.runtime.sendMessage({ type: "AUTH_REQUEST" }, (refreshResponse) => {\n          if (refreshResponse && refreshResponse.token) {\n            localStorage.setItem("jwt_token", refreshResponse.token);\n            iframe.contentWindow.postMessage({\n              type: "JWT_TOKEN",\n              token: refreshResponse.token\n            }, BACKEND_URL);\n          }\n        });\n      }\n    });\n  </script>\n</body>\n</html>`,
