        language: 'python',
        content: `"""\nБазовый класс для всех парсеров\n"""\nimport json\nimport datetime\nimport random\nimport asyncio\nfrom abc import ABC, abstractmethod\nfrom pathlib import Path\nfrom typing import Dict, Optional\n\nfrom models.task import Task\nfrom services.web_service import WebService\nfrom services.html_parser import HtmlParser\n\n\nclass BaseParser(ABC):\n    """Базовый класс для всех парсеров с общей логикой"""\n\n    def __init__(self, task: Task, web_service: WebService) -> None:\n        self.task = task\n        self.webpage_name = task.get_webpage_name()\n        self.number = task.chapter\n        self.web_service = web_service\n        self.html_parser = HtmlParser  # Используем класс напрямую\n        self.delay_range = (1, 3)\n\n    @abstractmethod\n    async def parse(self):\n        """Основной метод парсинга"""\n        pass\n\n    async def connect(self, url: str, domain: str = None) -> Optional[str]:\n        """Подключение к сайту с задержкой"""\n        delay = random.randint(*self.delay_range)\n        await asyncio.sleep(delay)\n        return await self.web_service.get_page_content(url, self.task.tool, domain=domain)\n\n    def extract_text(self, html_content: str, tag: str, extra_tag: str) -> str:\n        """Извлечение текста из HTML с использованием тегов"""\n        parser = self.html_parser(html_content)\n        return parser.parse_by_config(tag, extra_tag)\n\n    def save_chapters(self, chapters: Dict) -> Path:\n        """Сохранение глав в JSON файл"""\n        novel_folder = Path("novels") / self.task.title\n        novel_folder.mkdir(parents=True, exist_ok=True)\n        novel_file_path = novel_folder / f"{self.task.title}.json"\n\n        with open(novel_file_path, "w", encoding="UTF-8") as file:\n            json.dump(chapters, file, ensure_ascii=False, indent=4)\n\n        return novel_file_path\n\n    def save_error_data(self, chapters: Dict) -> Optional[Path]:\n        """Сохранение собранных данных в директорию ошибок"""\n        if not chapters:\n            return None\n\n        error_dir = Path("novels") / "error"\n        error_dir.mkdir(parents=True, exist_ok=True)\n\n        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")\n        error_file_path = error_dir / f"{self.task.title}_error_{timestamp}.json"\n\n        with open(error_file_path, "w", encoding="UTF-8") as file:\n            json.dump(chapters, file, ensure_ascii=False, indent=4)\n\n        return error_file_path\n`,
