        content: `from aiogram import Router, F\nfrom aiogram.types import Message\nfrom aiogram.filters import StateFilter\nfrom loguru import logger\n\nfrom bot.database import Database\nfrom bot.services.mistral import MistralService\nfrom bot.fsm import UserSession, DialogueState\nfrom bot.handlers.commands import get_session\n\nrouter = Router()\nmistral = MistralService()\n\n\n@router.message(StateFilter(DialogueState.ASKING))\nasync def handle_answer(message: Message, db: Database):\n    """Обработка ответа пользователя"""\n    user_id = message.from_user.id\n    user_answer = message.text.strip()\n    session = get_session(user_id)\n\n    if not session.current_topic:\n        await message.answer("🤔 Сначала выбери тему через /topic")\n        session.state = DialogueState.IDLE\n        return\n\n    # Оцениваем ответ\n    evaluation = await mistral.evaluate_answer(\n        question=session.current_question or "",\n        user_answer=user_answer,\n        topic=session.current_topic\n    )\n\n    # Добавляем в контекст\n    session.add_to_context(f"Q: {session.current_question}")\n    session.add_to_context(f"A: {user_answer}")\n\n    # Проверяем, есть ли в ответе новые термины\n    new_topics = await mistral.extract_topics(user_answer)\n    for topic in new_topics:\n        if not await db.topic_exists(topic):\n            topic_id = await db.add_topic(topic)\n            await db.add_user_topic(user_id, topic_id)\n            logger.debug(f"Добавлена новая тема из ответа: {topic}")\n\n    # Формируем ответ\n    if evaluation.get("is_correct", True):\n        session.streak += 1\n        motivation = get_motivation(session.streak)\n        await message.answer(f"{motivation}\\n\\n{evaluation.get('explanation', 'Верно!')}")\n        \n        # Следующий вопрос\n        next_question = await mistral.generate_question(\n            topic=session.current_topic,\n            context=session.get_context_summary()\n        )\n        session.current_question = next_question\n        session.add_to_context(f"Next Q: {next_question}")\n        \n        await message.answer(f"📝 **Вопрос:**\\n{next_question}")\n        \n        # Обновляем прогресс\n        topics = await db.get_user_topics(user_id)\n        current_topic_db = next((t for t in topics if t['name'] == session.current_topic), None)\n        if current_topic_db:\n            new_progress = min(100, current_topic_db['progress'] + 5)\n            topic_id = await db.get_topic_by_name(session.current_topic)\n            await db.update_progress(user_id, topic_id, new_progress)\n    else:\n        session.streak = 0\n        explanation = await mistral.explain_concept(session.current_topic)\n        await message.answer(\n            f"❌ Не совсем так...\\n\\n"\n            f"{evaluation.get('explanation', '')}\\n\\n"\n            f"📖 **Объяснение:**\\n{explanation}\\n\\n"\n            f"Давай ещё разок? Тот же вопрос:"\n        )\n        await message.answer(session.current_question)\n        session.state = DialogueState.EXPLAINING\n\n\n@router.message(StateFilter(DialogueState.EXPLAINING))\nasync def handle_after_explanation(message: Message, db: Database):\n    """Повторная попытка после объяснения"""\n    user_id = message.from_user.id\n    session = get_session(user_id)\n\n    # Возвращаем в режим вопроса\n    session.state = DialogueState.ASKING\n    await handle_answer(message, db)\n\n\ndef get_motivation(streak: int) -> str:\n    """Получить мотивирующую фразу в зависимости от серии"""\n    motivations = {\n        1: "👍 Неплохо!",\n        2: "🔥 Хорош!",\n        3: "🚀 Продолжай в том же духе!",\n        4: "💪 Ты машина!",\n        5: "🏆 Легенда! 5 правильных ответов подряд!",\n    }\n    return motivations.get(min(streak, 5), "🔥🔥🔥")\n`,
