        content: `#!/usr/bin/env python3\n"""\nСкрипт для извлечения текста из RTF файлов\n"""\n\nimport re\nimport sys\nfrom pathlib import Path\n\n\ndef rtf_decode(text):\n    """Простая функция для декодирования RTF содержимого"""\n    # Убираем RTF теги\n    text = re.sub(r'\\\\[a-z]+\\d*', '', text)\n    # Заменяем специальные символы\n    text = text.replace('\\\\}', '}').replace('\\\\{', '{').replace('\\\\\\\\', '\\\\')\n    # Убираем лишние пробелы и переносы\n    text = re.sub(r'\\s+', ' ', text)\n    return text.strip()\n\n\ndef extract_text_from_rtf(file_path):\n    """Извлечение текста из RTF файла"""\n    try:\n        with open(file_path, 'rb') as f:\n            content = f.read()\n        \n        # Пробуем разные кодировки\n        encodings = ['utf-8', 'windows-1251', 'cp1251', 'latin-1']\n        decoded_content = None\n        \n        for encoding in encodings:\n            try:\n                decoded_content = content.decode(encoding)\n                break\n            except UnicodeDecodeError:\n                continue\n        \n        if decoded_content is None:\n            # Если не удалось декодировать, используем decode с ошибками\n            decoded_content = content.decode('utf-8', errors='ignore')\n        \n        # Применяем декодирование RTF\n        cleaned_content = rtf_decode(decoded_content)\n        \n        # Ищем только текст между основными RTF тегами\n        import re\n        # Ищем текст после \\fs24\\cf0 и до конца параграфа\n        matches = re.findall(r'\\\\fs24\\\\cf0(.*?)(?=\\\\par|$)', cleaned_content)\n        \n        if matches:\n            extracted_text = ' '.join(matches)\n            # Убираем лишние пробелы и специальные символы\n            extracted_text = re.sub(r'\\s+', ' ', extracted_text).strip()\n            return extracted_text\n        else:\n            return cleaned_content\n    \n    except Exception as e:\n        print(f"Ошибка при чтении файла {file_path}: {e}")\n        return None\n\n\ndef main():\n    if len(sys.argv) != 2:\n        print("Использование: python extract_rtf.py <путь_к_rtf_файлу>")\n        sys.exit(1)\n    \n    file_path = sys.argv[1]\n    text = extract_text_from_rtf(file_path)\n    \n    if text:\n        print(text)\n    else:\n        print("Не удалось извлечь текст из файла")\n\n\nif __name__ == "__main__":\n    main()`,
