        path: `sql\\ddl_from_dwh01\\cisco.sql`,
        language: 'sql',
        content: `CREATE OR REPLACE VIEW cisco.view_employee_events_sessions_by_date\nAS SELECT el.login AS employee_login,\n    ees.session_date,\n    min(ees.session_start)::time without time zone AS min_session_start,\n    max(ees.session_stop)::time without time zone AS max_session_stop,\n    sum(ees.session_duration) AS total_sessions_time,\n    max(ees.crosses_midnight::integer)::boolean AS crosses_midnight\n   FROM ( SELECT combined.employee_login,\n            combined.session_date,\n            combined.session_start,\n            combined.session_stop,\n            combined.session_stop - combined.session_start AS session_duration,\n            combined.crosses_midnight\n           FROM ( SELECT se.employee_login,\n                    se.session_date,\n                    se.session_start,\n                    min(ste.session_stop) AS session_stop,\n                    false AS crosses_midnight\n                   FROM ( SELECT ee.employee_login,\n                            date(ee.log_timestamp) AS session_date,\n                            ee.log_timestamp AS session_start\n                           FROM cisco.employee_event ee\n                          WHERE ee.connect_status = 4) se\n                     LEFT JOIN ( SELECT ee2.employee_login,\n                            date(ee2.log_timestamp) AS session_date,\n                            ee2.log_timestamp AS session_stop\n                           FROM cisco.employee_event ee2\n                          WHERE ee2.connect_status = 2) ste ON se.employee_login = ste.employee_login AND ste.session_date = se.session_date AND ste.session_stop > se.session_start\n                  WHERE ste.session_stop IS NOT NULL\n                  GROUP BY se.employee_login, se.session_date, se.session_start\n                UNION ALL\n                 SELECT ste.employee_login,\n                    ste.session_date,\n                    date_trunc('day'::text, ste.session_stop) AS session_start,\n                    ste.session_stop,\n                    false AS crosses_midnight\n                   FROM ( SELECT ee2.employee_login,\n                            date(ee2.log_timestamp) AS session_date,\n                            ee2.log_timestamp AS session_stop\n                           FROM cisco.employee_event ee2\n                          WHERE ee2.connect_status = 2) ste\n                     LEFT JOIN ( SELECT ee.employee_login,\n                            date(ee.log_timestamp) AS session_date,\n                            ee.log_timestamp AS session_start\n                           FROM cisco.employee_event ee\n                          WHERE ee.connect_status = 4) se ON se.employee_login = ste.employee_login AND ste.session_date = se.session_date AND ste.session_stop > se.session_start\n                  WHERE se.employee_login IS NULL\n                UNION ALL\n                 SELECT se.employee_login,\n                    se.session_date,\n                    se.session_start,\n                    date_trunc('day'::text, se.session_start) + '23:59:59'::interval AS session_stop,\n                    true AS crosses_midnight\n                   FROM ( SELECT ee.employee_login,\n                            date(ee.log_timestamp) AS session_date,\n                            ee.log_timestamp AS session_start\n                           FROM cisco.employee_event ee\n                          WHERE ee.connect_status = 4) se\n                     LEFT JOIN ( SELECT ee2.employee_login,\n                            date(ee2.log_timestamp) AS session_date,\n                            ee2.log_timestamp AS session_stop\n                           FROM cisco.employee_event ee2\n                          WHERE ee2.connect_status = 2) ste ON se.employee_login = ste.employee_login AND ste.session_date = se.session_date AND ste.session_stop > se.session_start\n                  WHERE ste.employee_login IS NULL) combined) ees\n     LEFT JOIN cisco.employee_login el ON el.id = ees.employee_login\n  GROUP BY el.login, ees.session_date;`,
