        path: `scripter\\main.py`,
        language: 'python',
        content: `import os\nimport whisper\nfrom datetime import datetime\nfrom pathlib import Path\n\n# Добавить ffmpeg в PATH\nffmpeg_path = Path(__file__).parent / "ffmpeg" / "ffmpeg-8.1-essentials_build" / "bin"\nos.environ["PATH"] = str(ffmpeg_path) + os.pathsep + os.environ.get("PATH", "")\n\nMODEL_DIR = Path(__file__).parent / "models"\nMODEL_SIZES = {\n    "tiny": "tiny.pt",\n    "base": "base.pt",\n    "small": "small.pt",\n    "medium": "medium.pt",\n    "large": "large.pt",\n}\n\n\ndef get_model_path(model_size: str) -> Path:\n    """Получить путь к файлу модели"""\n    return MODEL_DIR / MODEL_SIZES.get(model_size, f"{model_size}.pt")\n\n\ndef ensure_model_exists(model_size: str) -> None:\n    """Проверить наличие модели и предложить скачать если нет"""\n    model_path = get_model_path(model_size)\n\n    if not model_path.exists():\n        print(f"Модель '{model_size}' не найдена в {model_path}")\n        print("Первая загрузка может занять время (модель ~1-3 ГБ)...")\n        print("После загрузки модель сохранится локально.")\n\n        MODEL_DIR.mkdir(parents=True, exist_ok=True)\n\n        model = whisper.load_model(model_size, download_root=str(MODEL_DIR))\n        print(f"Модель сохранена в: {model_path}")\n    else:\n        print(f"Модель '{model_size}' найдена локально")\n\n\ndef transcribe_audio(file_path, model_size="medium"):\n    """Упрощенная транскрибация аудио в текст"""\n\n    output_file = f"{file_path.rsplit('.', 1)[0]}_{datetime.now().strftime('%H%M%S')}.txt"\n\n    ensure_model_exists(model_size)\n\n    print("Загружаю модель...")\n    model = whisper.load_model(model_size, download_root=str(MODEL_DIR))\n\n    print("Обрабатываю аудио...")\n    result = model.transcribe(\n        file_path,\n        language="ru",\n        verbose=True\n    )\n\n    with open(output_file, "w", encoding="utf-8") as f:\n        f.write(result["text"])\n\n    print(f"Готово! Результат в: {output_file}")\n    return result, output_file\n\n\nif __name__ == "__main__":\n    transcribe_audio("ZOOM0004.MP3")\n    transcribe_audio("Головин.MP3")\n`,
        size: 2006
