        language: 'python',
        content: `import json\nfrom loguru import logger\nfrom .giga import AskGiga\nfrom .retrieval_service import load_embmodel_and_get_data_qdrant, load_cemodel_and_get_reranker_result\nfrom typing import List\nfrom aice_app.utils.schemas import Space\nfrom aice_app.utils.utils import ActiveDirectory, convert_json_payload\nfrom aice_app.utils.constants import  QDRANT_API_KEY, QDRANT_URL, DROPDOWN_SPACES_COLLECTION, AVAILABLE_SPACES, HAVE_NOT_PERMISSIONS, LANGFUSE_SECRET_KEY, LANGFUSE_PUBLIC_KEY, LANGFUSE_BASE_URL\nfrom aice_app.utils.qdrant import Qdrant\nfrom langfuse import observe, Langfuse\n\n@observe(name='get_available_user_spaces', as_type='tool')\ndef get_available_user_spaces(employee_login: str):\n    """\n    :param employee_login: sbr corporate employee_login\n    :param get_keys: bool, does objects must be space keys or space names\n    :return: list with available spaces\n    """\n    active_directory = ActiveDirectory()\n    user_groups = active_directory.get_user_groups(employee_login)\n\n    user_groups.extend([key for key in AVAILABLE_SPACES.keys()])\n\n    return user_groups\n\n\n@observe(name='main_llm_process', as_type='generation')\ndef chat_main(question: str, space_key: str, employee_login: str, use_all_spaces: bool) -> tuple:\n    """\n    main core chat scenario function\n    :param question: user's question to agent\n    :param space_key: confluence space key\n    :param employee_login: sbr corporate employee_login\n    :param use_all_spaces: sign of a search for all spaces\n    :return: tuple with finded document id and answer string\n    """\n\n    user_groups: list = get_available_user_spaces(employee_login)\n\n    document_ids = []\n\n    if use_all_spaces == True:\n        search_result = load_embmodel_and_get_data_qdrant(question, user_groups, limit=30, use_all_spaces=True)\n    else:\n        collection_name = space_key\n        if collection_name not in user_groups:\n            return  [],  HAVE_NOT_PERMISSIONS\n\n        search_result = load_embmodel_and_get_data_qdrant(question, collection_name, limit=30)\n\n    json_data = convert_json_payload(search_result)\n    top_documents = rerank_data(question, json_data)\n\n    ask_giga = AskGiga()\n    document_ids, answer = ask_giga(question, top_documents)\n\n    return document_ids, answer, search_result\n\n@observe(name='cross_encoder_io', as_type='retriever')\ndef rerank_data(question: str, input_json: str):\n\n    output_list = []\n    json_data = json.loads(input_json)\n    for item in json_data:\n        output_list.append(item['document'])\n\n    documents_rank = load_cemodel_and_get_reranker_result(question, output_list)\n\n    if documents_rank is not None:\n        combined = []\n        for rank in documents_rank:\n            corpus_id = rank['corpus_id']\n            score = rank['score']\n            document_info = json_data[corpus_id]          \n            combined.append({**document_info,  'score': score})\n\n        top_documents = sorted(combined, key=lambda x: x['score'], reverse=True)[:7]\n        result_json = json.dumps(top_documents, ensure_ascii=False, indent=2).__str__()\n    else:\n        result_json = "Данные отсутствуют"\n\n    return result_json\n\ndef get_spaces_from_confluence(employee_login) -> List[Space]:\n    """\n    :param employee_login: sbr corporate employee login\n    :return: list with spaces for current \n    """\n    user_groups = get_available_user_spaces(employee_login)\n\n    db = Qdrant(QDRANT_URL, QDRANT_API_KEY)\n    raw_spaces = db.get_spaces(spaces=DROPDOWN_SPACES_COLLECTION)\n    filtered_spaces = []\n\n    for raw_space in raw_spaces:\n\n        space_id = raw_space.id\n        space_payload = raw_space.payload\n        space_key = space_payload.get("space_key")\n        space_name = space_payload.get("space_name")\n\n        if space_key in user_groups:\n\n               filtered_spaces.append(\n                       Space(\n                           id=space_id,\n                           key=space_key,\n                           name=space_name\n                           )\n               )\n\n    return filtered_spaces\n`,
