        content: `from os import getenv\nfrom loguru import logger\nfrom qdrant_client import models, QdrantClient\nfrom qdrant_client.models import Distance, VectorParams, PointStruct, Filter, FieldCondition, Range\nfrom qdrant_client.http.exceptions import UnexpectedResponse, ResponseHandlingException, ApiException\nfrom .constants import DROPDOWN_SPACES_COLLECTION\nfrom langfuse import observe, Langfuse\n\n\nclass Qdrant:\n    """\n    Class implements qdrant database connnectivity\n    """\n    def __init__(self, qdrant_url: str, qdrant_api_key: str, qdrant_client = QdrantClient) -> list[list]:\n        """\n        :param qdrant_url: qdrant database ip address \n        :param qdrant_api_key: qdrant access secret key\n        """\n        self.qdrant_url: str = qdrant_url\n        self.qdrant_api_key: str = qdrant_api_key\n        self.qdrant_client = qdrant_client\n\n    def get_spaces(self, spaces:str) -> list[list,]:\n        """\n        returns all confluience space names and keys\n        """\n        client = self.__client_connect()\n\n        spaces = client.search_groups(\n                collection_name=spaces,\n                     limit=2000,\n                     group_by='space_name',\n                     query_vector=[0.1 for i in range(1024)],\n                     with_payload=['space_key', 'space_name'],\n                     group_size=1\n                     )\n\n        return [hit[0] for hit in [group.hits for group in spaces.groups]]\n\n    @observe(name='qdrant_single_space_vector_search', as_type='retriever')\n    def vector_search(self, vector: str, limit=3, collection_name=None, length=0) -> dict:\n        """\n        realizes database vector search\n        in collections by arg\n        """\n\n        client = self.__client_connect()\n\n        query_filter=Filter(\n            must=[\n               FieldCondition(\n                  key="len",\n                  range=Range(\n                     gte=length,\n                  ),\n               ), \n                {\n                    'key':'space_key', \n                    'match': {\n                        'value':collection_name}\n                        }\n            ]\n        )\n\n        search_result = client.query_points(\n                collection_name=DROPDOWN_SPACES_COLLECTION,\n                query=vector,\n                query_filter=query_filter,\n                with_payload=True,\n                search_params=models.SearchParams(\n                                exact=True),\n                limit=limit\n                ).points\n\n        return search_result\n\n    @observe(name='qdrant_multiple_space_vector_search', as_type='retriever')\n    def all_spaces_vector_search(self, vector: str, limit=3, spaces: list=None, length=0) -> dict:\n        """\n        realizes database vector search\n        in all user collections\n        """\n\n        client = self.__client_connect()\n\n        must=[FieldCondition(key="len",range=Range(gte=length)),         models.FieldCondition(\n                        key="space_key",\n                                    match=models.MatchAny(\n                                                        any=spaces\n                                                                    ))]\n\n\n        query_filter=Filter(must=must)\n\n        search_result = client.query_points(\n                collection_name=DROPDOWN_SPACES_COLLECTION,\n                query=vector,\n                query_filter=query_filter,\n                with_payload=True,\n                search_params=models.SearchParams(\n                              exact=True),\n                limit=limit\n                ).points\n\n        return search_result\n\n    def __client_connect(self) -> QdrantClient:\n        """\n        connection establish method\n        """\n        try:\n            client = self.qdrant_client(url=self.qdrant_url, api_key=self.qdrant_api_key)\n        except (UnexpectedResponse, ResponseHandlingException, ApiException) as exception:\n            logger.error(f'Exception near Qdrant database connection and spaces scroll - {exception}')\n            raise\n\n        return client\n`,
